// Reference specification (informal):
// starts_with(s, p) is true iff p is empty OR
// (s.len() >= p.len() AND for all i < p.len(): s[i] == p[i]).

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Empty prefix matches everything.
    if p.is_empty() {
        return true;
    }
    // If v is shorter than prefix, it cannot match.
    if v.len() < p.len() {
        return false;
    }
    // Compare element-wise up to prefix length.
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Preserve relative order by iterating in order and pushing matches.
    let mut filtered: Vec<Vec<char>> = Vec::new();
    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s);
        }
    }
    filtered
}

fn main() {
    // Example usage:
    let xs = vec![
        vec!['a', 'b', 'c'],
        vec!['a', 'b'],
        vec!['b', 'a'],
        vec![],
    ];
    let p = vec!['a', 'b'];

    let out = filter_by_prefix(xs, p);
    // out should be: [['a','b','c'], ['a','b']]
    println!("{:?}", out);
}